    n = P["nodes"][nid]
    op = n["op"]
    if op == "constd":
        v = n["value"]
    elif op == "zero":
        v = 0
    elif op == "one":
        v = 1
    else:
        raise ValueError(f"not concrete-evaluable: {op}")
    v &= mask(width_of(P, nid))
    memo[nid] = v
    return v


def sym_eval(P, nid, state_var, input_vars, memo):
    if nid in memo:
        return memo[nid]
    n = P["nodes"][nid]
    op = n["op"]
    w = width_of(P, nid)
    if op == "zero":
        v = z3.BitVecVal(0, w)
    elif op == "one":
        v = z3.BitVecVal(1, w)
    elif op == "constd":
        v = z3.BitVecVal(n["value"], w)
    elif op == "input":
        v = input_vars[nid]
    elif op == "state":
        v = state_var
    elif op == "not":
        v = ~sym_eval(P, n["a"], state_var, input_vars, memo)
    elif op in ("add", "sub", "mul", "and", "eq", "ult"):
        a = sym_eval(P, n["a"], state_var, input_vars, memo)
        b = sym_eval(P, n["b"], state_var, input_vars, memo)
        if op == "add":
            v = a + b
        elif op == "sub":
            v = a - b
        elif op == "mul":
            v = a * b
        elif op == "and":
            v = a & b
        elif op == "eq":
