        elif op == "ult":
            v = z3.If(z3.ULT(a, b), z3.BitVecVal(1, 1), z3.BitVecVal(0, 1))
    elif op == "ite":
        c = sym_eval(P, n["cond"], state_var, input_vars, memo)
        a = sym_eval(P, n["a"], state_var, input_vars, memo)
        b = sym_eval(P, n["b"], state_var, input_vars, memo)
        v = z3.If(c == z3.BitVecVal(1, 1), a, b)
    else:
        raise ValueError(f"cannot symbolically evaluate {op!r}")
    memo[nid] = v
    return v


def try_prove(path):
    with open(path) as fh:
        P = parse(fh.read())
    assert len(P["states"]) == 1, "need exactly one state"
    sid = P["states"][0]
    W = width_of(P, sid)
    init_val = eval_concrete(P, P["inits"][sid], {})

    state_var = z3.BitVec("state", W)
    input_vars = {i: z3.BitVec(P["nodes"][i]["name"], width_of(P, i)) for i in P["inputs"]}
    memo = {}
    next_expr = sym_eval(P, P["nexts"][sid], state_var, input_vars, memo)
    bad_exprs = [sym_eval(P, b, state_var, input_vars, memo) for b in P["bads"]]
    bad_bool = z3.Or([e == z3.BitVecVal(1, 1) for e in bad_exprs]) if bad_exprs else z3.BoolVal(False)
    con_exprs = [sym_eval(P, c, state_var, input_vars, memo) for c in P["constraints"]]
    ok_bool = z3.And([e == z3.BitVecVal(1, 1) for e in con_exprs]) if con_exprs else z3.BoolVal(True)

    for k in range(1, W + 1):
        g = 1 << k
        r = init_val & (g - 1)
        mask_bv = z3.BitVecVal(g - 1, W)
        r_bv = z3.BitVecVal(r, W)
        inv = (state_var & mask_bv) == r_bv

