        safe_res = s2.check()
        if safe_res == z3.unsat:
            return {"g": g, "r": r, "k": k}
    return None


for f in ["par32.btor2", "frozen.btor2", "parity.btor2", "blocked.btor2", "input.btor2", "deep.btor2", "miss.btor2"]:
    import os
