    except Exception as exc:
        print(json.dumps({"kind": "partial", "progress": {
            "note": f"congruence procedure inapplicable: {exc}",
            "bound_reached": -1}}))
        return
    if found is None:
        print(json.dumps({"kind": "partial", "progress": {
            "note": "no power-of-two congruence invariant (mod 2..2^W) is "
                    "both inductive and bad-free",
